import{_ as r,a0 as p,w as i,s as a,ao as b,I as s,x as t,a1 as u,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"Ubuntu One 的10个鲜为人知的功能 | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu One 的10个鲜为人知的功能 | LCTT (201402) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu One 的10个鲜为人知的功能 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu One 的10个鲜为人知的功能 | LCTT (201402) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201402/10 Lesser Known Ubuntu One Features","title":"Ubuntu One 的10个鲜为人知的功能","tag":"201402","desc":""},"relativePath":"201402/10 Lesser Known Ubuntu One Features.md","filePath":"[post].md"}'),d={name:"201402/10 Lesser Known Ubuntu One Features.md"};function l(U,n,O,m,g,T){const e=p("Link");return i(),a("div",null,[n[11]||(n[11]=b('<h1 id="ubuntu-one-的10个鲜为人知的功能" tabindex="-1">Ubuntu One 的10个鲜为人知的功能 <a class="header-anchor" href="#ubuntu-one-的10个鲜为人知的功能" aria-label="Permalink to “Ubuntu One 的10个鲜为人知的功能”">​</a></h1><p>尽管 Ubuntu One 看上去像一个仅支持 Ubuntu 文件同步服务，但实际上它可以在 Windows，Android，iOS 和网页上使用。而且，Ubuntu One 提供了5GB的免费存储空间。</p><p><img src="http://www.efytimes.com/admin/useradmin/photo/Kj3S10756PM1212014.jpg" alt=""></p><p>根据 howtogeek.com 的介绍，用户通过 Ubuntu One 可以在线共享文件或目录，推送音乐到手机，在所有的设备上同步已安装的应用等等。下面我们一起来看一下10个Ubuntu One你也许不知道的功能。</p><p>1.<strong>同步目录</strong> - 在默认设置下，Ubuntu 系统仅仅会同步用户主目录下的 Ubuntu One 目录。但是你可以用鼠标右击任意文件夹，然后点击 Ubuntu One 菜单，选择 Synchronize This Folder 开始同步，这样就可以将这个目录加入到 Ubuntu One 中了。在 Ubuntu One 中，你可以管理所有的已同步目录。</p><p>2.<strong>限制带宽</strong> - 在默认设置下，Ubuntu One 会使用系统全部的网络带宽来上传或下载文件。但是，如果你接入网络速度比较慢，它也允许设定上传和下载速度。你可以在 Ubuntu One 主窗口的设置界面里找到带宽设置。</p><p>3.<strong>在Windows上使用Ubuntu One</strong> - Ubuntu One 不是仅仅在 Linux 上运行，它也有一个 Windows 的客户端，提供完整的文件同步支持。Ubuntu One 是一个跨平台的文件同步服务，即使是完全没有接触过 Ubuntu 的 Windows 用户，也可以使用 Ubuntu One 提供的服务。</p><p>4.<strong>共享文件</strong> - 在文件管理器的鼠标右键菜单或者 Ubuntu One 网站，你可以将文件或者目录共享到因特网上，也可以选择分享给指定的 Ubuntu One 用户。</p><p>5.<strong>同步已安装应用</strong> - Ubuntu One 可以在你所有的计算机上同步你从Ubuntu的软件中心安装的应用，这样你就可以轻松管理已安装的应用。</p><p>6.<strong>手机应用</strong> - Ubuntu One 为 Android，iPhone，iPad和Ipod Touch 提供了应用。通过这些应用，你可以在移动设备上轻松访问 Ubuntu One 的文件。</p><p>7.<strong>自动上传智能手机中的相片</strong> - 移动应用还支持自动上传手机中的相片到 Ubuntu One 云服务器中，这样你可以轻松地在所有的设备上浏览你的相片。</p><p>8.<strong>在线音乐播放</strong> - Ubuntu One 还提供了 Ubuntu One 音乐应用，支持 Android和iOS。你可以通过智能手机在任意地方欣赏你的音乐，也可以选择缓存到本地离线播放。</p><p>9.<strong>同步联系人</strong> - Ubuntu One可以同步你的联系人并在线保存。目前，你可以在 Ubuntu One 网页上导入 Facebook 联系人，或者手动添加。早期版本的 Ubuntu 还支持同步 Evolution 邮件客户端的联系人，但在新的12.04版本中不支持从 Thunderbird 邮件客户端同步联系人。</p><p>10.<strong>在浏览器中管理你的文件</strong> - 在电脑上安装了 Ubuntu One 后，可以在 Ubuntu One 网页上管理本地文件。你可以在浏览器中下载文件，上传文件，或者管理现有的文件。</p><hr>',15)),s("p",null,[n[1]||(n[1]=t("via: ",-1)),u(e,{href:"http://www.efytimes.com/e1/fullnews.asp?edid=127466"},{default:o(()=>[...n[0]||(n[0]=[t("http://www.efytimes.com/e1/fullnews.asp?edid=127466",-1)])]),_:1})]),s("p",null,[n[4]||(n[4]=t("译者：",-1)),u(e,{href:"https://github.com/zpl1025"},{default:o(()=>[...n[2]||(n[2]=[t("zpl1025",-1)])]),_:1}),n[5]||(n[5]=t(" 校对：",-1)),u(e,{href:"https://github.com/carolinewuyan"},{default:o(()=>[...n[3]||(n[3]=[t("Caroline",-1)])]),_:1})]),s("p",null,[n[8]||(n[8]=t("本文由 ",-1)),u(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...n[6]||(n[6]=[t("LCTT",-1)])]),_:1}),n[9]||(n[9]=t(" 原创翻译，",-1)),u(e,{href:"http://linux.cn/"},{default:o(()=>[...n[7]||(n[7]=[t("Linux中国",-1)])]),_:1}),n[10]||(n[10]=t(" 荣誉推出",-1))])])}const L=r(d,[["render",l]]);export{C as __pageData,L as default};
